                    function uiLibrary:MapValue(inputValue, inputMin, inputMax, outputMin, outputMax)
                        return (1 - (inputValue - inputMin) / (inputMax - inputMin)) * outputMin + (inputValue - inputMin) / (inputMax - inputMin) * outputMax
                    end
