                            panel.Container.Position = UDim2.fromOffset(frame.AbsolutePosition.X + frame.AbsoluteSize.X + 4, frame.AbsolutePosition.Y + 1)
                        end
                        local function updateSize()
                            local maxWidth = 60

                            for key9, child in next, panel.Inner:GetChildren()do

