                        for i = 1, #folders do

                            local folderPath = folders[i]

                            if not isfolderFn(folderPath) then
                                makefolder(folderPath)
                            end
                        end
                    end
                    function configManager:CheckFolderTree()
                        if not isfolderFn(self.Folder) then
                            configManager:BuildFolderTree()
                            task.wait()
                        end
