                    -- Serialize non-ignored toggles and options to JSON; write to file unless skipWrite
                    function configManager:Save(configName, skipWrite)
                        if not configName then
                            return false, 'no config file is selected'
                        end

                        configManager:CheckFolderTree()

                        local configPath = self.Folder .. '/settings/' .. configName .. '.json'
                        local savedConfig = {objects = {}}

                        for key2, toggle in next, toggles do

                            if self.Ignore[key2] then
                                continue
                            end

                            table.insert(savedConfig.objects, self.Parser[toggle.Type].Save(key2, toggle))
                        end
                        for key3, option in next, options do

                            if not self.Parser[option.Type] then
                                continue
                            end
                            if self.Ignore[key3] then
                                continue
                            end

                            table.insert(savedConfig.objects, self.Parser[option.Type].Save(key3, option))
                        end

                        local success, resultOrError = pcall(httpService.JSONEncode, httpService, savedConfig)

                        if not success then
                            return false, 'failed to encode data'
                        end
                        if not skipWrite then
                            writefile(configPath, resultOrError)
                        end

                        return true, resultOrError
                    end
                    -- Load a config from a decoded table or from a JSON file in the settings folder
                    function configManager:Load(configOrName)
                        if not configOrName then
                            return false, 'no config file is selected'
                        end
                        if type(configOrName) == 'table' then
                            for key4, savedObject in next, configOrName.objects do

                                if self.Parser[savedObject.type] then
                                    task.spawn(function()
                                        self.Parser[savedObject.type].Load(savedObject.idx, savedObject)
                                    end)
                                end
