                    -- Apply a custom or built-in theme to the library and matching options
                    function themeManager:ApplyTheme(themeName)
                        if not themeName then
                            return
                        end

                        local customTheme = self:GetCustomTheme(themeName)
                        local customTheme2 = customTheme or self.BuiltInThemes[themeName]

                        if not customTheme2 then
                            return
                        end
                        if self.Library.InnerVideoBackground ~= nil then
                            self.Library.InnerVideoBackground.Visible = false
                        end

                        local themeScheme = customTheme2[2]

                        for key, themeValue in next, customTheme or themeScheme do

                            if key:find('Color') then
                                self.Library[key] = Color3.fromHex(themeValue)

                                if options[key] then
                                    options[key]:SetValueRGB(Color3.fromHex(themeValue))
                                end
                            else
                                self.Library[key] = themeValue

                                if options[key] then
                                    options[key]:SetValue(themeValue)
                                end
                            end
                        end

                        self:ThemeUpdate()
                    end
                    -- Copy current theme option values into the library and refresh registry colors
                    function themeManager:ThemeUpdate()
                        if self.Library.InnerVideoBackground ~= nil then
                            self.Library.InnerVideoBackground.Visible = false
                        end

                        local themeFields = {
                            'Contrast',
                            'Saturation',
                            'Brightness',
                            'BlurSize',
                            'FontColor',
                            'RiskColor',
                            'MainColor',
                            'AccentColor',
                            'BackgroundColor',
                            outlineColorNameRef,
                            'SwordColor',
                            'ItemType',
                            'BackTransparency',
                            'BackColor',
                            'SwordTransparency',
                            'SwordReflectance',
                            'SwordMaterial',
                            'SwordSpeed',
                        }

                        for key2, field in next, themeFields do

                            if options and options[field] then
                                self.Library[field] = options[field].Value
                            end
                        end

                        self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor)

                        self.Library:UpdateColorsUsingRegistry()
                    end
                    -- Load the saved default theme, falling back to the built-in default
                    function themeManager:LoadDefault()
                        local themeName = 'Default'
                        local contents = isfile(self.Folder .. '/themes/default.txt') and readfile(self.Folder .. '/themes/default.txt')
                        local isBuiltIn = true

                        if contents then
                            if self.BuiltInThemes[contents] then
                                themeName = contents
                            elseif self:GetCustomTheme(contents) then
                                themeName = contents
                                isBuiltIn = false
                            end
                        elseif self.BuiltInThemes[self.DefaultTheme] then
                            themeName = self.DefaultTheme
                        end
                        if isBuiltIn then
                            options.ThemeManager_ThemeList:SetValue(themeName)
                        else
                            self:ApplyTheme(themeName)
                        end
                    end
                    function themeManager:SaveDefault(themeName2)
                        writefile(self.Folder .. '/themes/default.txt', themeName2)
                    end
                    function themeManager:Delete(fileName)
                        if not fileName then
                            return false, 'no config file is selected'
                        end

                        local filePath = self.Folder .. '/themes/' .. fileName

                        if not isfile(filePath) then
                            return false, 'invalid file'
                        end

                        local success, resultOrError = pcall(delfile, filePath)

                        if not success then
                            return false, 'delete file error'
                        end

                        return true
                    end
                    function themeManager:GetCustomTheme(fileName2)
                        if not fileName2 then
                            return
                        end

                        local filePath = self.Folder .. '/themes/' .. fileName2

                        if not isfile(filePath) then
                            return nil
                        end

                        local contents = readfile(filePath)
                        local success2, resultOrError2 = pcall(httpService.JSONDecode, httpService, contents)

                        if not success2 then
                            return nil
                        end

                        return resultOrError2
                    end
                    -- Save current theme option values to a custom theme JSON file
                    function themeManager:SaveCustomTheme(fileName3)
                        if not fileName3 or fileName3:gsub(' ', '') == '' then
                            return self.Library:Notify('Invalid file name for theme (empty)', 3)
                        end

                        local themeData = {}
                        local themeFields = {
                            'Contrast',
                            'Saturation',
                            'Brightness',
                            'BlurSize',
                            'FontColor',
                            'RiskColor',
                            'MainColor',
                            'AccentColor',
                            'BackgroundColor',
                            outlineColorNameRef,
                            'ItemType',
                            'SwordColor',
                            'BackTransparency',
                            'BackColor',
                            'SwordTransparency',
                            'SwordReflectance',
                            'SwordMaterial',
                            'SwordSpeed',
                        }

                        for key3, field in next, themeFields do

                            if options[field] then
                                if not field:find('Color') then
                                    themeData[field] = options[field].Value
                                else
                                    themeData[field] = options[field].Value:ToHex()
                                end
                            end
                        end

                        writefile(self.Folder .. '/themes/' .. fileName3, httpService:JSONEncode(themeData))
                    end
                    -- List custom theme file names in the themes folder
                    function themeManager:ReloadCustomThemes()
                        local files = listfiles(self.Folder .. '/themes')
                        local themeNames = {}

                        for i = 1, #files do

                            local filePath = files[i]

                            if filePath:sub(-5) == '.json' then
                                local matchStart = filePath:find('.json', 1, true)
                                local sub = filePath:sub(matchStart, matchStart)

                                while sub ~= '/' and sub ~= '\\' and sub ~= '' do

                                    matchStart = matchStart - 1
                                    sub = filePath:sub(matchStart, matchStart)
                                end

                                if sub == '/' or sub == '\\' then
                                    table.insert(themeNames, filePath:sub(matchStart + 1))
                                end
                            end
                        end

                        return themeNames
                    end
                    function themeManager:SetLibrary(library)
                        self.Library = library
                    end
                    -- Create every folder along the theme folder path
                    function themeManager:BuildFolderTree()
                        local paths = {}
                        local parts = self.Folder:split('/')

                        for i = 1, #parts do

                            paths[#paths + 1] = table.concat(parts, '/', 1, i)
                        end

                        table.insert(paths, self.Folder .. '/themes')

                        for i = 1, #paths do

                            local path = paths[i]

                            if not isfolder(path) then
                                makefolder(path)
                            end
                        end
                    end
                    function themeManager:SetFolder(folder)
