                                if not decodeOk then
                                    local jsonOk, jsonResult = pcall(function()
                                        return HttpService2:JSONDecode(pastedText)
                                    end)
                                    decodeOk = jsonOk
                                    decoded = jsonResult
                                end
                                if decodeOk and type(decoded) == "table" and decoded.objects then
                                    local success, err = self:Load(decoded)
                                    local errorMessage = err
                                    if success then
                                        self.Library:Notify("Loaded copied config!")
                                        return
                                    end
                                    return self.Library:Notify("Failed to load config: " .. errorMessage)
                                end
                                return self.Library:Notify("Failed to load paste config, did you copy it properly?")
                            end
                        end,
                    })
                    -- Copy the current config to the clipboard as base64
                    groupbox:AddButton("Copy config to clipboard", function()
                        local saveManager_ConfigList = options.SaveManager_ConfigList.Value
                        local success, result = self:Save(saveManager_ConfigList, true)
                        local resultOrError = result
                        if success then
                            setclipboard(base64.encode(resultOrError))
                            self.Library:Notify(string.format("copied config %q", saveManager_ConfigList))
                            return
                        end
                        return self.Library:Notify("Failed to copy config: " .. resultOrError)
                    end)
                    configManager:SetIgnoreIndexes({"SaveManager_ConfigList", "SaveManager_ConfigName", "SaveManager_ConfigTextInput"})
                end
            end)()
        end
