                -- Looping ambience sounds selectable by name
                local ambienceSounds = {
                    Rain = "rbxassetid://9112858162",
                    ["Heavy Rain"] = "rbxassetid://9064263922",
                    ["Light Rain And Thunder"] = "rbxassetid://9120018695",
                    ["Forest Rain Night"] = "rbxassetid://5356133579",
                    ["Windy Day"] = "rbxassetid://159798309",
                    City = "rbxassetid://238385471",
                }
                local tab = tabbox4:AddTab("ambience")
                tab:AddToggle("ambience_enabled", {Text = "enabled", Default = false})
                local ambienceNames = {}
                for ambienceName in ambienceSounds do
                    table.insert(ambienceNames, ambienceName)
                end
                table.sort(ambienceNames, function(a, b)
                    return #a < #b
                end)
                tab:AddDropdown("ambience_value", {Text = "selected", Values = ambienceNames, Default = "Heavy Rain"})
                tab:AddSlider("ambience_volume", {Text = "volume", Default = 0.5, Min = 0.1, Max = 10, Rounding = 1, Suffix = "db", Compact = true})
                local sound = createInstance("Sound", {
                    Parent = game:GetService("SoundService"),
                    Looped = true,
                    Volume = 0.5,
                    SoundId = ambienceSounds["Heavy Rain"],
                })
                for _, option in {Toggles.ambience_enabled, Options.ambience_volume, Options.ambience_value} do
                    option:OnChanged(function()
                        if sound.SoundId ~= ambienceSounds[Options.ambience_value.Value] then
                            sound.TimePosition = 0
                        end
                        sound.Playing = Toggles.ambience_enabled.Value
                        sound.Volume = Options.ambience_volume.Value
                        sound.SoundId = ambienceSounds[Options.ambience_value.Value]
                    end)
                end
            end
            do
                local tabbox5 = tabs.world:AddRightTabbox()
                do
                    -- Bloom override that restores the original properties when disabled
                    local bloomEffect = createInstance("BloomEffect", {Parent = game:GetService("Lighting"), Enabled = false, Intensity = 0.6, Size = 26, Threshold = 0.4});
                    (protectinstance or function() end)(bloomEffect)
                    local tab = tabbox5:AddTab("bloom")
                    tab:AddToggle("bloom_enabled", {Text = "enable", Default = false})
                    tab:AddSlider("bloom_intensity", {
                        Text = "intensity",
                        Default = tonumber(string.format("%.2f", bloomEffect.Intensity)),
                        Min = 0,
                        Max = 10,
                        Suffix = "",
                        Rounding = 1,
                        Compact = true,
                    })
                    tab:AddSlider("bloom_size", {Text = "size", Default = bloomEffect.Size, Min = 0, Max = 100, Suffix = "", Rounding = 0, Compact = true})
                    tab:AddSlider("bloom_threshold", {
                        Text = "threshold",
                        Default = tonumber(string.format("%.2f", bloomEffect.Threshold)),
                        Min = 0.1,
                        Max = 1,
                        Suffix = "",
                        Rounding = 2,
                        Compact = true,
                    })
                    local originalBloom = {Intensity = bloomEffect.Intensity, Threshold = bloomEffect.Threshold, Size = bloomEffect.Size, Enabled = bloomEffect.Enabled}
                    local updateBloom = function()
                        local bloom_enabled = Toggles.bloom_enabled.Value

                        if bloom_enabled then
                            bloomEffect.Enabled = true
                            bloomEffect.Size = Options.bloom_size.Value
                            bloomEffect.Intensity = Options.bloom_intensity.Value
                            bloomEffect.Threshold = Options.bloom_threshold.Value
                        else
                            for key, originalValue in originalBloom do

                                bloomEffect[key] = originalValue
                            end
                        end
                    end
                    Toggles.bloom_enabled:OnChanged(updateBloom)
                    Options.bloom_intensity:OnChanged(updateBloom)
                    Options.bloom_size:OnChanged(updateBloom)
                    Options.bloom_threshold:OnChanged(updateBloom)
                end
                -- Sun rays override that restores the original properties when disabled
                local sunRays = game:GetService("Lighting"):FindFirstChild("SunRays") or Instance.new("SunRaysEffect", game:GetService("Lighting"));
                (protectinstance or function() end)(sunRays)
                local tab = tabbox5:AddTab("sun rays")
                tab:AddToggle("sunrays_enabled", {Text = "override", Default = false})
                tab:AddSlider("sunrays_intensity", {
                    Text = "intensity",
                    Default = tonumber(string.format("%.2f", sunRays.Intensity)),
                    Min = 0,
                    Max = 1,
                    Suffix = "",
                    Rounding = 2,
                    Compact = true,
                }):AddSlider("sunrays_spread", {Text = "spread", Default = sunRays.Spread, Min = 0, Max = 1, Suffix = "", Rounding = 2, Compact = true})
                local originalSunRays = {Intensity = sunRays.Intensity, Spread = sunRays.Spread, Enabled = sunRays.Enabled}
                local updateSunRays = function()
                    local sunrays_enabled = Toggles.sunrays_enabled.Value

                    if sunrays_enabled then
                        sunRays.Enabled = true
                        sunRays.Spread = Options.sunrays_spread.Value
                        sunRays.Intensity = Options.sunrays_intensity.Value
                    else
                        for key, originalValue in originalSunRays do

                            sunRays[key] = originalValue
                        end
                    end
                end
                Toggles.sunrays_enabled:OnChanged(updateSunRays)
                Options.sunrays_intensity:OnChanged(updateSunRays)
                Options.sunrays_spread:OnChanged(updateSunRays)
            end
            do
                -- Camera settings: anti-flashbang, FOV changer, aspect ratio and blur
                local groupbox2 = tabs.world:AddRightGroupbox("camera")
                groupbox2:AddToggle("camera_anti_flashbang", {Text = "anti flashbang", Default = false})
                groupbox2:AddToggle("camera_fov_changer", {
