                local blurEffect = createInstance("BlurEffect", {Parent = game:GetService("Lighting"), Enabled = true, Size = 0})
                groupbox2:AddSlider("camera_blur", {Text = "blur", Default = 0, Min = 0, Max = 10, Suffix = "x", Rounding = 1, Compact = true}):OnChanged(function(blurSize)
                    blurEffect.Size = blurSize
                end)
            end
            do
                -- Lighting overrides: per-property toggles that reapply when the game changes them
                local Lighting3 = game:GetService("Lighting")
                local sliderSettings = {
                    FogEnd = {min = 0, max = 10000, rounding = 0, suffix = "studs"},
                    FogStart = {min = 0, max = 1000, rounding = 0, suffix = "studs"},
                    ExposureCompensation = {min = -5, max = 5, rounding = 1, suffix = ""},
                    Brightness = {min = 0, max = 10, rounding = 1, suffix = ""},
                    ClockTime = {min = 0, max = 24, rounding = 1, suffix = "h"},
                }
                local groupbox3 = tabs.world:AddLeftGroupbox("lighting")
                for _, text in pairs({
                    "Ambient",
                    "ColorShift_Bottom",
                    "ColorShift_Top",
                    "FogColor",
                    "FogEnd",
                    "FogStart",
                    "ExposureCompensation",
                    "Brightness",
                    "ClockTime",
                    "GlobalShadows",
                }) do
                    local default = Lighting3[text]
                    local kind = typeof(default)
                    local isApplying = false
                    local overrideEnabled = false
                    local default2 = default
                    local applyOverride = function()
                        isApplying = true
                        if not overrideEnabled then
                            Lighting3[text] = default
                        else
                            Lighting3[text] = default2
                        end
                        isApplying = false
                    end
                    if kind == "Color3" then
                        groupbox3:AddToggle("lighting_toggle_" .. text, {Text = text, Default = false}):AddColorPicker("lighting_color" .. text, {Default = default, Title = text .. " Color"})
                        Toggles["lighting_toggle_" .. text]:OnChanged(function(enabled)
                            overrideEnabled = enabled
                            applyOverride()
                        end)
                        Options["lighting_color" .. text]:OnChanged(function(color)
                            default2 = color
                            applyOverride()
                        end)
                    elseif kind == "number" then
                        local sliderSetting = sliderSettings[text]
                        local toggle = groupbox3:AddToggle("lighting_toggle_" .. text, {Text = text, Default = false})
                        local sliderDependencyBox = groupbox3:AddDependencyBox()
                        sliderDependencyBox:SetupDependencies({{toggle, true}})
                        sliderDependencyBox:AddSlider("lighting_number_" .. text, {
                            Default = string.format("%." .. sliderSetting.rounding .. "f", default),
                            Min = sliderSetting.min,
                            Max = sliderSetting.max,
                            Rounding = sliderSetting.rounding,
                            Suffix = sliderSetting.suffix,
                            Compact = true,
                            Text = text,
                        })
                        Toggles["lighting_toggle_" .. text]:OnChanged(function(enabled)
                            overrideEnabled = enabled
                            applyOverride()
                        end)
                        Options["lighting_number_" .. text]:OnChanged(function(amount)
                            default2 = amount
                            applyOverride()
                        end)
                    elseif kind == "boolean" then
                        groupbox3:AddToggle("lighting_bool_" .. text, {Default = default, Text = text})
                        Toggles["lighting_bool_" .. text]:OnChanged(function(enabled)
                            overrideEnabled = enabled
                            default2 = enabled
                            applyOverride()
                        end)
                    end
                    Lighting3:GetPropertyChangedSignal(text):Connect(function()
                        if not isApplying then
                            default = Lighting3[text]
                            if overrideEnabled then
                                applyOverride()
                            end
                        end
                    end)
                end
            end
            do
                -- Debounced ESP color-changed event
                local thread = nil
