                local groupbox15 = tabs.misc:AddLeftGroupbox("loadout")
                groupbox15:AddToggle("auto_select_enabled", {Text = "auto select", Default = false})
                local constants = waitForPath(ReplicatedStorage, "Modules", "CONSTANTS")
                local module3 = require(constants)
                local itemLibrary = waitForPath(ReplicatedStorage, "Modules", "ItemLibrary")
                local module4 = require(itemLibrary)
                local module5 = require(waitForPath(ReplicatedStorage, "Modules", "ShopLibrary"))
                local releasedWeapons = callWithEnv(module5.GetReleasedOwnableWeapons, module5, module3.WEAPON_EARLY_ACCESS_TIME_OFFSET)
                local getWeaponNames = function(filter)
                    local weaponNames = {}
                    local class = filter and filter.class
                    for weaponName, itemInfo in module4.Items do
                        if table.find(releasedWeapons, weaponName) and (not class or itemInfo.Class == class) then
                            table.insert(weaponNames, weaponName)
                        end
                    end
                    table.sort(weaponNames, function(a, b)
                        return #a > #b
                    end)
                    if class then
                        local defaultWeapon = nil
                        for _, weaponName in weaponNames do
                            if table.find(module3.DEFAULT_WEAPONS, weaponName) then
                                defaultWeapon = weaponName
                            end
                        end
                        return weaponNames, defaultWeapon
                    end
                    return weaponNames, nil
                end
                local dropdownFlags = {}
                for _, class in {"Primary", "Secondary", "Melee", "Utility"} do
                    local weaponNames, default = getWeaponNames({class = class})
                    local flag = "auto_select_" .. class
                    groupbox15:AddDropdown(flag, {Values = weaponNames, Default = default, Text = class:lower(), Illegal = true})
                    table.insert(dropdownFlags, flag)
                end
