                    tab4:AddToggle("chat_spam_enabled", {Text = "enabled", Default = false})
                    tab4:AddToggle("chat_spam_order", {Text = "in order", Tooltip = "chats go in order of creation, not randomly", Default = false})
                    tab4:AddDropdown("chat_spam_mode", {Values = {"custom"}, Default = "custom", Text = "chat mode"})
                    tab4:AddDropdown("chat_spam_text", {
                        Values = {},
                        Multi = true,
                        Illegal = true,
                        Text = "random custom text",
                        AllowNull = true,
                        Callback = function(selection)
                            local custom = {}
                            for text, isSelected in selection do
                                if isSelected then
                                    table.insert(custom, text)
                                end
                            end
                            chat_spam.default.custom = custom
                            Options.chat_spam_text:SetValues(custom)
                        end,
                    })
                    tab4:AddInput("chat_spam_input", {
                        Numeric = false,
                        Finished = true,
                        Text = "add custom text",
                        Placeholder = "message...",
                        Callback = function(text)
                            if #text == 0 or Options.chat_spam_text.Value[text] then
                                return
                            end
                            table.insert(Options.chat_spam_text.Values, text)
                            Options.chat_spam_text.Value[text] = true
                            Options.chat_spam_text:SetValue(Options.chat_spam_text.Value)
                            Options.chat_spam_text:SetValues(Options.chat_spam_text.Values)
                        end,
                    })
                    -- Rebuild chat spam modes from files in the chat folder plus the built-in defaults
                    local refreshChatModes = function()
                        local fileModes = {}
                        for _, filePath in fileSystem.listfiles("chat") do
                            local parts = readfile(filePath):split("\n")
                            if #parts == 0 then
                                Library:Notify("invalid file for chat spam:" .. filePath)
                            else
                                local parts2 = filePath:split("\\")
                                fileModes[parts2[#parts2]] = parts
                            end
                        end
                        local modes = Options.chat_spam_mode.Values
                        for _, mode in modes do
                            if not fileModes[mode] and not chat_spam.default[mode] then
                                table.remove(modes, table.find(modes, mode))
                                chat_spam.messages[mode] = nil
                            end
                        end
                        for modeName, messages in fileModes do
                            if not table.find(modes, modeName) then
                                table.insert(modes, modeName)
                            end
                            chat_spam.messages[modeName] = messages
                        end
                        for modeName in chat_spam.default do
                            if not table.find(modes, modeName) then
                                table.insert(modes, modeName)
                            end
                        end
                        Options.chat_spam_mode:SetValues(modes)
                    end
