                                    local changed2 = self.whitelist.changed
                                    local to_cache = self.to_cache
                                    local thread = nil
                                    local cacheDescendant = function(descendant)
                                        local className2 = descendant.ClassName
                                        local properties = to_cache[className2]
                                        if properties and instance(descendant, className2) then
                                            local originals = {}
