                                    -- Build a Color/NumberSequence from numbered color options (option list cached per name)
                                    local buildSequence = function(optionName, isTransparency)
                                        local cached = sequenceOptionCache[optionName]
                                        local sequenceOptions, optionCount

                                        if not cached then
                                            sequenceOptions, optionCount = {}, 0

                                            while true do

                                                local option = Options[optionName .. optionCount + 1] or Options[optionName]

                                                if not option then
                                                    break
                                                end

